import { ExtrudeGeometry } from "three";
import { CrossedWheelShape, type CrossedWheelShapeOptions } from "../../shapes/CrossedWheelShape";

export interface CrossedWheelGeometryOptions extends CrossedWheelShapeOptions {
  /** Extrusion depth. Defaults to `0.06` — clock wheels are thin brass. */
  depth?: number;
}

/**
 * Extruded **crossed-out wheel** — a clock or watch wheel: a toothed rim carried on radial spokes. See
 * {@link CrossedWheelShape} for the anatomy and the horological vocabulary.
 *
 * Where {@link GearGeometry} is a solid disc with a bore, this removes the web between hub and rim. Every tooth
 * option is inherited, so the crossings compose with the tooth profile — a crossed-out escapement wheel is
 * `{ crossings: 5, tipWidth: 0, lean: 1 }`.
 *
 * The clamps are load-bearing rather than defensive: the hub is held clear of the bore and the rim keeps
 * backing inward of the tooth valleys, since without either the cut-outs reach through and the teeth come away
 * from the wheel. {@link crossings} reports `0` when no annulus was left to cut, leaving the web solid.
 *
 * Local frame: **centered on its own thickness**, spanning `±depth / 2` in Z, matching
 * {@link GearGeometry} so a rank of wheels on one arbor lines up on the plane they turn in.
 *
 * Material groups: **none** — one material for the whole wheel.
 *
 * @example
 * ```typescript
 * const wheel = new Mesh(new CrossedWheelGeometry({ teeth: 60, crossings: 5 }), brass);
 * ```
 */
export class CrossedWheelGeometry extends ExtrudeGeometry {
  /** The bore radius actually used, after clamping inside the tooth profile. */
  readonly holeRadius: number;
  /** Crossings actually cut. `0` means the web was left solid. */
  readonly crossings: number;
  /** The hub radius actually used, after clamping clear of the bore. */
  readonly hubRadius: number;
  /** Inner edge of the rim — where the cut-outs stop and tooth backing begins. */
  readonly rimInnerRadius: number;
  /** The crossing width actually used, after clamping so spokes cannot overlap at the hub. */
  readonly crossingWidth: number;

  constructor({ depth = 0.06, ...shapeOptions }: CrossedWheelGeometryOptions = {}) {
    const shape = new CrossedWheelShape(shapeOptions);

    super(shape, { depth, bevelEnabled: false });

    // Center on the thickness rather than extruding forward from zero.
    this.translate(0, 0, -depth / 2);

    this.holeRadius = shape.holeRadius;
    this.crossings = shape.crossings;
    this.hubRadius = shape.hubRadius;
    this.rimInnerRadius = shape.rimInnerRadius;
    this.crossingWidth = shape.crossingWidth;
  }
}
